INSERT INTO "pages" VALUES(2,'link','友链',replace('# 友情链接\n\nHere is my network neighborhood. 很高兴与优秀的你们在此相遇。\n\n---\n\n## 🌟 推荐博客\n> 以下友链对本站建设有突出贡献或对本人具有重大意义\n\n<div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; margin: 24px 0;">\n  \n  <a href="https://www.chillg.de/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 12px; padding: 16px; border: 1px solid rgba(128,128,128,0.2); border-radius: 16px; background: rgba(128,128,128,0.05); transition: all 0.3s;">\n    <img src="https://file.8888998.xyz/2025/09/13/1757754994823-4mmgxd.webp" style="width: 50px; height: 50px; border-radius: 50%; object-fit: cover;" alt="浅草物语" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: bold; font-size: 14px; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;">\n        浅草物语\n        <span style="font-size: 10px; background: rgba(59,130,246,0.1); color: #3b82f6; padding: 1px 6px; border-radius: 4px;">自荐</span>\n      </div>\n      <div style="font-size: 12px; opacity: 0.6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">清净的一亩三分地</div>\n    </div>\n  </a>\n\n  <a href="https://blog.zhheo.com/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 12px; padding: 16px; border: 1px solid rgba(128,128,128,0.2); border-radius: 16px; background: rgba(128,128,128,0.05); transition: all 0.3s;">\n    <img src="https://bu.dusays.com/2022/12/28/63ac2812183aa.png" style="width: 50px; height: 50px; border-radius: 50%; object-fit: cover;" alt="张洪Heo" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: bold; font-size: 14px; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;">\n        张洪Heo\n        <span style="font-size: 10px; background: rgba(245,158,11,0.1); color: #f59e0b; padding: 1px 6px; border-radius: 4px;">技术</span>\n      </div>\n      <div style="font-size: 12px; opacity: 0.6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">分享设计与科技生活</div>\n    </div>\n  </a>\n\n  <a href="https://www.qcqx.cn" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 12px; padding: 16px; border: 1px solid rgba(128,128,128,0.2); border-radius: 16px; background: rgba(128,128,128,0.05); transition: all 0.3s;">\n    <img src="https://www.qcqx.cn/head.webp" style="width: 50px; height: 50px; border-radius: 50%; object-fit: cover;" alt="轻笑Chuckle" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: bold; font-size: 14px; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;">\n        轻笑Chuckle\n        <span style="font-size: 10px; background: rgba(16,185,129,0.1); color: #10b981; padding: 1px 6px; border-radius: 4px;">前端</span>\n      </div>\n      <div style="font-size: 12px; opacity: 0.6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">漫天倾尘,风中轻笑</div>\n    </div>\n  </a>\n\n  <a href="https://blog.anheyu.com/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 12px; padding: 16px; border: 1px solid rgba(128,128,128,0.2); border-radius: 16px; background: rgba(128,128,128,0.05); transition: all 0.3s;">\n    <img src="https://npm.elemecdn.com/anzhiyu-blog-static@1.0.4/img/avatar.jpg" style="width: 50px; height: 50px; border-radius: 50%; object-fit: cover;" alt="安知鱼" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: bold; font-size: 14px; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;">\n        安知鱼\n        <span style="font-size: 10px; background: rgba(139,92,246,0.1); color: #8b5cf6; padding: 1px 6px; border-radius: 4px;">主题</span>\n      </div>\n      <div style="font-size: 12px; opacity: 0.6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">生活明朗，万物可爱</div>\n    </div>\n  </a>\n\n  <a href="https://www.imaegoo.com/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 12px; padding: 16px; border: 1px solid rgba(128,128,128,0.2); border-radius: 16px; background: rgba(128,128,128,0.05); transition: all 0.3s;">\n    <img src="https://cdn.jsdelivr.net/npm/imaegoo/avatar.jpg" style="width: 50px; height: 50px; border-radius: 50%; object-fit: cover;" alt="iMaeGoo’s Blog" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: bold; font-size: 14px; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;">\n        iMaeGoo’s Blog\n        <span style="font-size: 10px; background: rgba(236,72,153,0.1); color: #ec4899; padding: 1px 6px; border-radius: 4px;">评论</span>\n      </div>\n      <div style="font-size: 12px; opacity: 0.6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">虹墨空间站</div>\n    </div>\n  </a>\n</div>\n\n---\n\n## 🤝 小伙伴\n> 那些人，那些事\n\n<div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 12px; margin: 24px 0;">\n\n  <a href="https://www.zmzaxg.top/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://zmzaxg.top/icon.ico" style="width: 40px; height: 40px; border-radius: 50%;" alt="zmzaxg" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">zmzaxg|blog社区</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">依旧是你，赫然如此</div>\n    </div>\n  </a>\n\n  <a href="https://www.xhily.com" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://www.xhily.com/wp-content/uploads/2018/03/cropped-favicon-32x32.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="无用笔记" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">无用笔记</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">念念不忘，必有回响</div>\n    </div>\n  </a>\n\n  <a href="https://blog.hzao.top/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://file.8888998.xyz/2025/09/13/1757755401334-qqvw2h.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="Hzao" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">Hzao</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">更好看的B站分享链接作者</div>\n    </div>\n  </a>\n\n  <a href="https://blog.cxplay.org/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://cdn.jsdelivr.net/gh/cxplay/core@latest/logo/cxplay.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="CXPLAY World" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">CXPLAY World</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">Share With You.</div>\n    </div>\n  </a>\n\n  <a href="https://blog.btwoa.com/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://file.8888998.xyz/2025/09/13/1757755414411-ohobvz.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="btwoa" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">btwoa</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">世界为你简单</div>\n    </div>\n  </a>\n\n  <a href="https://blog.gzzz.pro/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://file.8888998.xyz/2025/09/13/1757755432190-y9cc6u.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="Gzzz’s Blog" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">Gzzz’s Blog</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">逝者如斯夫，不舍昼夜。</div>\n    </div>\n  </a>\n\n  <a href="https://blog.imsyy.top/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://file.8888998.xyz/2025/09/20/1758354953950-n81mzc.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="無名小栈" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">無名小栈</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">分享技术与科技生活</div>\n    </div>\n  </a>\n\n  <a href="https://yuubari.cn/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://yuubari.cn/upload/3628985i.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="朝瓜夕拾" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">朝瓜夕拾</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">瓜瓜和果果的Blog</div>\n    </div>\n  </a>\n\n  <a href="https://baigei.cc" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://baigei.cc/wp-content/uploads/2024/10/cropped-1730017604-IMG_0739.jpeg" style="width: 40px; height: 40px; border-radius: 50%;" alt="baigeiの角落" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">baigeiの角落</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">一个平平无奇的小破站</div>\n    </div>\n  </a>\n\n  <a href="https://blog.liseezn.top/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://blog.liseezn.top/logo.webp" style="width: 40px; height: 40px; border-radius: 50%;" alt="Liseezn’blog" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">Liseezn’blog</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">分享个人学习，项目，及一些教程</div>\n    </div>\n  </a>\n\n  <a href="https://www.dorazhang.cn/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid rgba(128,128,128,0.15); border-radius: 12px; background: rgba(128,128,128,0.02); transition: all 0.2s;">\n    <img src="https://q2.qlogo.cn/headimg_dl?dst_uin=2078170660&spec=100" style="width: 40px; height: 40px; border-radius: 50%;" alt="Zyx的小窝" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">Zyx的小窝</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">人生海海，山山而川，不过尔尔。</div>\n    </div>\n  </a>\n\n</div>\n\n---\n\n## 👻 失联\n> 走丢了... 半年内站点未恢复或超时且未主动联系会被移至此处\n\n<div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 12px; margin: 24px 0; opacity: 0.6;">\n\n  <a href="https://blog.xiaohan-kaka.me/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px dashed rgba(128,128,128,0.25); border-radius: 12px; background: transparent; transition: all 0.2s;">\n    <img src="https://file.8888998.xyz/2025/09/13/1757755447048-ow4ivk.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="晓寒" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">晓寒地</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">醉后不知天在水，满船清梦压星河</div>\n    </div>\n  </a>\n\n  <a href="https://leslieblog.top/" target="_blank" style="text-decoration: none; color: inherit; display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px dashed rgba(128,128,128,0.25); border-radius: 12px; background: transparent; transition: all 0.2s;">\n    <img src="https://file.8888998.xyz/2025/09/13/1757755388154-ixpnjs.png" style="width: 40px; height: 40px; border-radius: 50%;" alt="LeslieAlexander" />\n    <div style="flex: 1; min-width: 0;">\n      <div style="font-weight: 600; font-size: 13px; margin-bottom: 2px;">LeslieAlexander`Blog</div>\n      <div style="font-size: 11px; opacity: 0.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">茶要泡开才好喝，人要想开才好过</div>\n    </div>\n  </a>\n\n</div>','\n',char(10)),1,1,1,'2026-05-23 18:31:12','2026-05-23T18:33:14.908Z');
